# -*- coding: utf-8 -*-
# HFSS (AEDT) IronPython script -- loop cell R4 (outer 6.6 mm, strip 1.2 mm, one diode in the top side), 9.0 mm period, RT/duroid 5880 3.175 mm, set the diode state of the built cell. Generated by lwmom (Phase 28).
# MODEL_ONLY / NOT_HFSS_VALIDATED. Diode MA4AGP907 (= MADP-000907-14020) from vendor-measured S-parameters (MEASURED_VENDOR_SPARAM): ON R only (2.4 ohm at 10 mA, 3.3 ohm at 5 mA), OFF C only (28.2 fF at 0 V); the measured ON reactance (-3.7 ohm) is not modelled; LS_NH = 0 (no series L visible in the data), 0.2 nH is an untested sensitivity option.
# AEDT calls: VERIFIED in AEDT (3x3 smoke build, 2026-10-24): CreatePolyline sheets, Unite, AssignPerfectE, AssignLumpedRLC with ONE element type per sheet (R only or C only).
# NOT yet run in AEDT: the single-type INDUCTOR boundary (UseInduct), AssignMaster/AssignSlave with a scan angle, AssignFloquetPort, EditLumpedRLC / DeleteBoundaries. Each is in a try/except that prints what to do by hand.
# L_s > 0 is built as a SERIES CHAIN of two single-type boundaries (R or C, then L) joined by a 0.1 mm perfect-conductor island (hfss_chain, Phase 20 R2): HFSS Lumped RLC boundaries are not guaranteed to combine R, L, C in series.
import ScriptEnv
ScriptEnv.Initialize("Ansoft.ElectronicsDesktop")
oDesktop.RestoreWindow()

def attrs(name, material, solve_inside, color="(255 128 0)", transp=0):
    return ["NAME:Attributes", "Name:=", name, "Flags:=", "", "Color:=", color, "Transparency:=", transp,
            "PartCoordinateSystem:=", "Global", "UDMId:=", "", "MaterialValue:=", '"' + material + '"',
            "SurfaceMaterialValue:=", '""', "SolveInside:=", solve_inside, "IsMaterialEditable:=", True,
            "UseMaterialAppearance:=", False, "IsLightweight:=", False]

def mm(v):
    return repr(float(v)) + "mm"

def poly_sheet(oEditor, name, pts, z, color="(255 128 0)"):
    pl = ["NAME:PolylineParameters", "IsPolylineCovered:=", True, "IsPolylineClosed:=", True,
          ["NAME:PolylinePoints"] + [["NAME:PLPoint", "X:=", mm(x), "Y:=", mm(y), "Z:=", z] for (x, y) in list(pts) + [pts[0]]],
          ["NAME:PolylineSegments"] + [["NAME:PLSegment", "SegmentType:=", "Line", "StartIndex:=", k, "NoOfPoints:=", 2] for k in range(len(pts))],
          ["NAME:PolylineXSection", "XSectionType:=", "None", "XSectionOrient:=", "Auto", "XSectionWidth:=", "0mm",
           "XSectionTopWidth:=", "0mm", "XSectionHeight:=", "0mm", "XSectionNumSegments:=", "0", "XSectionBendType:=", "Corner"]]
    oEditor.CreatePolyline(pl, attrs(name, "vacuum", True, color))

LS_NH = 0.0                # package inductance [nH]: 0 (measured: none visible); 0.2 = untested sensitivity, no prediction
STATE = "OFF"              # the state to put on the open model: "ON" or "OFF"
ROT_DEG = 0.0              # rotation of the loop AND the diode axis about the cell centre [deg] (0 or 20; 40 would overlap the neighbours)
P = 9.0; H = 3.175; LID = 25.0
SO = 6.6; WR = 1.2; GAP = 0.6; ISL = 0.1
R_ON = "2.4ohm"; C_OFF = "0.0282pF"   # measured MA4AGP907: ON R 2.4 ohm at 10 mA (3.3 ohm at 5 mA, 2.0 ohm at 15 mA); OFF C 28.2 fF at 0 V (27.6 fF at -5 V)

import math
import math
oProject = oDesktop.GetActiveProject()
oDesign = oProject.GetActiveDesign()
oBnd = oDesign.GetModule("BoundarySetup")
Z = mm(H)
A = math.radians(ROT_DEG)
def rot(pt):
    return (pt[0] * math.cos(A) - pt[1] * math.sin(A), pt[0] * math.sin(A) + pt[1] * math.cos(A))
h = SO / 2.0
yt = h - WR / 2.0
n_el = 2 if LS_NH > 0 else 1
el = (GAP - (n_el - 1) * ISL) / n_el
x0 = -GAP / 2.0
line = (rot((x0, yt)), rot((x0 + el, yt)))
kind = "R" if STATE == "ON" else "C"
args = ["NAME:D0_RLC", "Objects:=", ["D0"],
        ["NAME:CurrentLine", "Start:=", [mm(line[0][0]), mm(line[0][1]), Z], "End:=", [mm(line[1][0]), mm(line[1][1]), Z]],
        "RLC Type:=", "Parallel",
        "UseResist:=", kind == "R", "Resistance:=", R_ON if kind == "R" else "0ohm",
        "UseInduct:=", False, "Inductance:=", "0nH",
        "UseCap:=", kind == "C", "Capacitance:=", C_OFF if kind == "C" else "0pF"]
try:
    oBnd.EditLumpedRLC("D0_RLC", args)
except Exception:
    oBnd.DeleteBoundaries(["D0_RLC"])
    oBnd.AssignLumpedRLC(args)
oDesktop.AddMessage(oProject.GetName(), oDesign.GetName(), 0, "State %s set on D0 (the inductor sheet D1, if any, is unchanged)." % STATE)
